insert into rackets (id, slug, brand_id, name, release_year, balance_point_mm, shaft_flex, shaft_diameter_mm, frame_shape, frame_material, max_tension_min_lbs, max_tension_max_lbs, length_mm, string_pattern, msrp, currency, play_style_tags, skill_level, hero_image_url, hero_thumb_url, summary_en, summary_vi) values
  ('r-astrox-88d-pro', 'astrox-88d-pro', 'b-yonex', 'Astrox 88D Pro', 2023, 298, 'stiff'::shaft_flex, 6.8, 'isometric'::frame_shape, ARRAY['HM Graphite', 'Namd', 'Tungsten'], 20, 28, 675, '22×21', 3390000, 'VND', ARRAY['attack', 'control']::play_style[], 'advanced'::skill_level, null, null, 'Head-heavy, stiff shaft — built for rear-court attack. It needs a full swing to give anything back.', 'Nặng đầu, thân cứng — dành cho lối đánh tấn công cuối sân. Phải vung hết tay thì vợt mới trả lực.'),
  ('r-astrox-99-pro', 'astrox-99-pro', 'b-yonex', 'Astrox 99 Pro', 2024, 300, 'stiff'::shaft_flex, 6.9, 'isometric'::frame_shape, ARRAY['HM Graphite', 'Namd', 'Nanometric'], 20, 28, 675, '22×21', 3690000, 'VND', ARRAY['attack']::play_style[], 'advanced'::skill_level, null, null, 'The heaviest head in the Astrox line. Clears come easy; the front court does not.', 'Đầu nặng nhất dòng Astrox. Cú phông rất nhẹ nhàng, nhưng trên lưới thì không.'),
  ('r-astrox-88s-pro', 'astrox-88s-pro', 'b-yonex', 'Astrox 88S Pro', 2023, 291, 'medium'::shaft_flex, 6.8, 'isometric'::frame_shape, ARRAY['HM Graphite', 'Namd'], 20, 28, 675, '22×21', 3350000, 'VND', ARRAY['all-round', 'speed']::play_style[], 'intermediate'::skill_level, null, null, 'The front-court half of the 88 pair. Even balance, softer shaft, quicker hands.', 'Nửa trên lưới của cặp 88. Cân bằng đều, thân mềm hơn, tay nhanh hơn.'),
  ('r-nanoflare-800-pro', 'nanoflare-800-pro', 'b-yonex', 'Nanoflare 800 Pro', 2023, 288, 'stiff'::shaft_flex, 6.6, 'aero-box'::frame_shape, ARRAY['HM Graphite', 'Toraycar'], 20, 28, 675, '22×21', 2590000, 'VND', ARRAY['speed', 'defence']::play_style[], 'advanced'::skill_level, null, null, 'A speed frame with a stiff shaft — rare, and it only pays back a fast arm.', 'Khung tốc độ nhưng thân cứng — hiếm gặp, và chỉ trả lực cho tay vung nhanh.'),
  ('r-nanoflare-700', 'nanoflare-700', 'b-yonex', 'Nanoflare 700', 2022, 285, 'medium'::shaft_flex, 6.8, 'aero-box'::frame_shape, ARRAY['Graphite', 'Nanomesh Neo'], 19, 27, 675, '22×21', 1890000, 'VND', ARRAY['speed', 'all-round']::play_style[], 'intermediate'::skill_level, null, null, 'The safest first speed racket. Nothing about it punishes a slow swing.', 'Cây vợt tốc độ đầu tiên an toàn nhất. Không có gì trừng phạt cú vung chậm.'),
  ('r-arcsaber-11-pro', 'arcsaber-11-pro', 'b-yonex', 'Arcsaber 11 Pro', 2022, 292, 'medium'::shaft_flex, 6.7, 'isometric'::frame_shape, ARRAY['HM Graphite', 'Namd', 'Nanomesh'], 20, 28, 675, '22×21', 3290000, 'VND', ARRAY['control', 'all-round']::play_style[], 'advanced'::skill_level, null, null, 'Holds the shuttle longer than anything else in this price band. Placement over power.', 'Giữ cầu lâu hơn mọi cây khác cùng tầm giá. Đặt cầu hơn là ăn lực.'),
  ('r-astrox-77-pro', 'astrox-77-pro', 'b-yonex', 'Astrox 77 Pro', 2022, 296, 'medium'::shaft_flex, 6.9, 'isometric'::frame_shape, ARRAY['Graphite', 'Namd'], 19, 27, 675, '22×21', 2490000, 'VND', ARRAY['attack', 'all-round']::play_style[], 'intermediate'::skill_level, null, null, 'Head-heavy without the stiff shaft tax. The usual step up from a starter racket.', 'Nặng đầu mà không phải trả giá bằng thân cứng. Bước nâng cấp quen thuộc từ vợt tập.'),
  ('r-thruster-ryuga-ii', 'thruster-ryuga-ii', 'b-victor', 'Thruster Ryuga II', 2023, 301, 'extra-stiff'::shaft_flex, 6.8, 'isometric'::frame_shape, ARRAY['Graphite', 'Nano Fortify TR+'], 20, 30, 675, '22×21', 3090000, 'VND', ARRAY['attack']::play_style[], 'advanced'::skill_level, null, null, 'Takes 30 lbs and asks for it. The stiffest shaft in this comparison set.', 'Chịu được 30 lbs và đòi hỏi đúng mức đó. Thân cứng nhất trong nhóm so sánh này.'),
  ('r-auraspeed-90k', 'auraspeed-90k', 'b-victor', 'Auraspeed 90K', 2022, 286, 'stiff'::shaft_flex, 6.6, 'aero-box'::frame_shape, ARRAY['Graphite', 'Hard Cored Technology'], 20, 30, 675, '22×21', 2490000, 'VND', ARRAY['speed', 'defence']::play_style[], 'advanced'::skill_level, null, null, 'Built for flat doubles exchanges. Loses to head-heavy frames from the back.', 'Sinh ra cho các pha cầu bằng trong đánh đôi. Từ cuối sân thì thua các khung nặng đầu.'),
  ('r-brave-sword-12', 'brave-sword-12', 'b-victor', 'Brave Sword 12', 2019, 290, 'medium'::shaft_flex, 7, 'aero-box'::frame_shape, ARRAY['Graphite', 'Nano Resin'], 19, 28, 675, '22×21', 1690000, 'VND', ARRAY['all-round', 'speed']::play_style[], 'beginner'::skill_level, null, null, 'Ten years old and still the honest answer for a first real racket.', 'Ra mắt đã mười năm và vẫn là câu trả lời thành thật cho cây vợt xịn đầu tiên.'),
  ('r-thruster-k-falcon', 'thruster-k-falcon', 'b-victor', 'Thruster K Falcon', 2021, 297, 'medium'::shaft_flex, 7, 'isometric'::frame_shape, ARRAY['Graphite'], 20, 28, 675, '22×21', 1290000, 'VND', ARRAY['attack']::play_style[], 'beginner'::skill_level, null, null, 'The cheapest head-heavy frame here that is not a counterfeit risk.', 'Khung nặng đầu rẻ nhất ở đây mà không kèm rủi ro hàng nhái.'),
  ('r-aeronaut-9000c', 'aeronaut-9000c', 'b-lining', 'Aeronaut 9000C', 2022, 295, 'medium'::shaft_flex, 7, 'aero-box'::frame_shape, ARRAY['Carbon Fibre', 'Aeronaut Tube'], 20, 28, 675, '22×21', 2590000, 'VND', ARRAY['all-round', 'control']::play_style[], 'intermediate'::skill_level, null, null, 'Trades power for a faster swing and a friendlier shaft. The comfortable one.', 'Đổi lực lấy nhịp vung nhanh hơn và thân vợt dễ chơi hơn. Cây êm tay nhất.'),
  ('r-axforce-90-dragon', 'axforce-90-dragon', 'b-lining', 'Axforce 90 Dragon', 2023, 299, 'stiff'::shaft_flex, 6.8, 'aero-box'::frame_shape, ARRAY['Carbon Fibre', 'Boron'], 20, 30, 675, '22×21', 3190000, 'VND', ARRAY['attack', 'speed']::play_style[], 'advanced'::skill_level, null, null, 'Head-heavy with an aero frame — heavy shots without the usual swing penalty.', 'Nặng đầu trên khung khí động — cú đánh nặng mà không phải trả giá bằng nhịp vung.'),
  ('r-windstorm-72', 'windstorm-72', 'b-lining', 'Windstorm 72', 2021, 283, 'flexible'::shaft_flex, 6.6, 'aero-box'::frame_shape, ARRAY['Carbon Fibre'], 18, 26, 675, '22×21', 1490000, 'VND', ARRAY['speed', 'defence']::play_style[], 'beginner'::skill_level, null, null, '72 grams and a flexible shaft. Kind to a sore shoulder, quiet from the back.', '72 gram với thân dẻo. Nhẹ nhàng cho vai đau, nhưng im tiếng ở cuối sân.'),
  ('r-fortius-11-power', 'fortius-11-power', 'b-mizuno', 'Fortius 11 Power', 2022, 297, 'stiff'::shaft_flex, 6.9, 'isometric'::frame_shape, ARRAY['Graphite', 'Toray M40X'], 20, 28, 675, '22×21', 2290000, 'VND', ARRAY['attack']::play_style[], 'intermediate'::skill_level, null, null, 'The quiet alternative to an Astrox, at two thirds of the price.', 'Lựa chọn kín tiếng thay cho Astrox, ở hai phần ba mức giá.'),
  ('r-altius-01-feel', 'altius-01-feel', 'b-mizuno', 'Altius 01 Feel', 2021, 287, 'medium'::shaft_flex, 6.8, 'isometric'::frame_shape, ARRAY['Graphite'], 19, 27, 675, '22×21', 1790000, 'VND', ARRAY['control', 'defence']::play_style[], 'intermediate'::skill_level, null, null, 'Even balance, medium shaft, nothing dramatic. That is the whole pitch.', 'Cân bằng đều, thân trung bình, không có gì kịch tính. Đó là toàn bộ điểm mạnh.'),
  ('r-power-control-900', 'power-control-900', 'b-kumpoo', 'Power Control 900', 2023, 293, 'medium'::shaft_flex, 6.9, 'isometric'::frame_shape, ARRAY['Carbon Fibre'], 20, 28, 675, '22×21', 1390000, 'VND', ARRAY['all-round']::play_style[], 'beginner'::skill_level, null, null, 'Sold mostly in club shops. The specs check out; the resale value does not.', 'Chủ yếu bán ở cửa hàng câu lạc bộ. Thông số thì ổn; giá bán lại thì không.'),
  ('r-feather-weight-55', 'feather-weight-55', 'b-apacs', 'Feather Weight 55', 2020, 281, 'flexible'::shaft_flex, 6.6, 'conventional'::frame_shape, ARRAY['Graphite'], 18, 24, 675, '22×21', 990000, 'VND', ARRAY['defence', 'speed']::play_style[], 'beginner'::skill_level, null, null, 'The lightest frame in the catalogue. Buy it for a recovering elbow, not for power.', 'Khung nhẹ nhất trong danh mục. Mua khi khuỷu tay đang hồi phục, không phải để lấy lực.')
