insert into sellers (id, slug, name, tier, city, rating, orders_count, dispute_rate, since, about_en, about_vi) values
  ('s-shuttle-pro-hn', 'shuttle-pro-hn', 'Shuttle Pro HN', 'authorised'::seller_tier, 'Hà Nội', 4.8, 1240, 0.004, 2019, 'Distributor agreement with Yonex Vietnam on file. Stringing on site, same day.', 'Có hợp đồng phân phối với Yonex Việt Nam. Đan lưới tại chỗ, trả trong ngày.'),
  ('s-dong-do-sports', 'dong-do-sports', 'Đông Đô Sports', 'authorised'::seller_tier, 'Hà Nội', 4.9, 2110, 0.003, 2016, 'Two shops in Đống Đa. Serials are photographed at intake and kept on file.', 'Hai cửa hàng ở Đống Đa. Số serial được chụp lúc nhập và lưu lại hồ sơ.'),
  ('s-vn-racket-store', 'vn-racket-store', 'VN Racket Store', 'verified'::seller_tier, 'TP. Hồ Chí Minh', 4.6, 860, 0.011, 2020, 'Online only. Ships nationwide in 2 days, 7-day return on unstrung frames.', 'Chỉ bán online. Giao toàn quốc trong 2 ngày, đổi trả 7 ngày với vợt chưa đan.'),
  ('s-cau-long-24h', 'cau-long-24h', 'Cầu Lông 24h', 'verified'::seller_tier, 'Đà Nẵng', 4.5, 410, 0.018, 2021, 'Club shop attached to three courts. Try before you buy on weekday evenings.', 'Cửa hàng gắn với ba sân tập. Được thử vợt trước khi mua vào các tối trong tuần.'),
  ('s-racket-lab-sg', 'racket-lab-sg', 'Racket Lab SG', 'verified'::seller_tier, 'TP. Hồ Chí Minh', 4.4, 320, 0.015, 2022, 'Specialises in used and open-box frames. Every listing carries intake photos.', 'Chuyên vợt cũ và hàng khui hộp. Mọi tin đăng đều kèm ảnh lúc nhập.'),
  ('s-smash-corner', 'smash-corner', 'Smash Corner', 'new'::seller_tier, 'Hải Phòng', 0, 6, 0, 2026, 'Approved in February. First three listings were checked by hand.', 'Được duyệt hồi tháng Hai. Ba tin đăng đầu đã được kiểm tra thủ công.')
