insert into guides (slug, title_en, title_vi, excerpt_en, excerpt_vi, read_minutes, tone) values
  ('spot-a-fake-astrox-88d-pro', 'How to spot a fake Astrox 88D Pro', 'Cách nhận ra Astrox 88D Pro giả', 'Serial placement, grommet finish, cone weight.', 'Vị trí số serial, đường viền gen, trọng lượng chuôi.', 6, 'default'),
  ('what-balance-point-changes', 'What balance point actually changes', 'Điểm cân bằng thực sự thay đổi điều gì', 'Read the ruler before you read the reviews.', 'Đọc thước cân bằng trước khi đọc đánh giá.', 4, 'default'),
  ('buying-used-what-to-check', 'Buying used: what to check in person', 'Mua vợt cũ: cần kiểm tra gì khi gặp trực tiếp', 'Cracks, replaced grommets, re-glued joints.', 'Vết nứt, gen thay mới, mối nối dán lại.', 8, 'used'),
  ('string-tension-for-your-level', 'String tension for your level, not your idol''s', 'Căng lưới theo trình độ của bạn, không phải của thần tượng', 'Why 30 lbs makes most club players worse.', 'Vì sao 30 lbs khiến phần lớn người chơi phong trào đánh tệ hơn.', 5, 'default')
insert into reviews (id, racket_id, author_name, tier, skill_level, format, position, string_model, tension_lbs, power, speed, control, comfort, body_en, body_vi, status, created_at) values
  ('rev-astrox-88d-pro-0', 'r-astrox-88d-pro', 'Thảo M.', 'community'::review_tier, 'advanced'::skill_level, 'singles'::match_format, 'mid'::court_position, 'Aerobite', 26, 3.5, 2.5, 4.5, 3, 'The shaft is softer than the marketing says. That suits me — smashes land where I aim rather than long.', 'Thân mềm hơn quảng cáo. Với tôi thì hợp — cú đập rơi đúng chỗ nhắm chứ không ra ngoài.', 'published'::review_status, '2026-08-01T00:00:00.000Z'),
  ('rev-astrox-88d-pro-1', 'r-astrox-88d-pro', 'Minh N.', 'purchase'::review_tier, 'intermediate'::skill_level, 'singles'::match_format, 'net'::court_position, 'Aerobite', 24, 4.5, 2.5, 4, 2.5, 'Light enough to defend flat drives all evening. It does not have a finishing shot in it.', 'Đủ nhẹ để đỡ cầu bằng suốt cả buổi. Nhưng không có cú kết thúc điểm.', 'published'::review_status, '2026-04-17T00:00:00.000Z'),
  ('rev-astrox-88d-pro-2', 'r-astrox-88d-pro', 'Hương T.', 'purchase'::review_tier, 'advanced'::skill_level, 'singles'::match_format, 'rear'::court_position, 'BG80', 28, 3.5, 3.5, 3.5, 3.5, 'Bought it for doubles at the net and it does that job. From the rear court it asks for a full swing every time.', 'Mua để đánh đôi trên lưới và nó làm tốt việc đó. Từ cuối sân thì lần nào cũng phải vung hết tay.', 'published'::review_status, '2026-07-01T00:00:00.000Z'),
  ('rev-astrox-88d-pro-3', 'r-astrox-88d-pro', 'Tuấn A.', 'owner'::review_tier, 'advanced'::skill_level, 'doubles'::match_format, 'mid'::court_position, 'Exbolt 63', 27, 4.5, 3, 3, 3.5, 'Second one I have owned. Same weight, same balance out of the box, which is not true of every brand at this price.', 'Đây là cây thứ hai tôi dùng. Trọng lượng và cân bằng giống hệt cây đầu, điều mà không phải hãng nào ở tầm giá này cũng làm được.', 'published'::review_status, '2026-07-13T00:00:00.000Z'),
  ('rev-astrox-88d-pro-4', 'r-astrox-88d-pro', 'Quang L.', 'owner'::review_tier, 'intermediate'::skill_level, 'doubles'::match_format, 'rear'::court_position, 'NBG95', 23, 4, 2.5, 3.5, 3.5, 'Holds shape after four months of twice-weekly play. Elbow gets sore if I string it any tighter.', 'Sau bốn tháng đánh hai buổi mỗi tuần vẫn giữ dáng. Căng cao hơn nữa là khuỷu tay đau.', 'published'::review_status, '2026-06-04T00:00:00.000Z'),
  ('rev-astrox-88d-pro-5', 'r-astrox-88d-pro', 'Linh P.', 'owner'::review_tier, 'advanced'::skill_level, 'singles'::match_format, 'rear'::court_position, 'NBG95', 24, 4.5, 2.5, 4, 3.5, 'Strung at 26 lbs with BG80. Repulsion is fine, but the sweet spot is smaller than I expected for the price.', 'Đan BG80 ở 26 lbs. Độ nảy ổn, nhưng vùng ngọt nhỏ hơn tôi nghĩ so với mức giá.', 'published'::review_status, '2026-07-24T00:00:00.000Z'),
  ('rev-astrox-88d-pro-6', 'r-astrox-88d-pro', 'Đức H.', 'owner'::review_tier, 'intermediate'::skill_level, 'singles'::match_format, 'net'::court_position, 'VBS-66N', 28, 3.5, 3, 3, 3, 'Heavier through the head than my last frame. Clears are easier from the back, but the third shot in a fast exchange is late.', 'Đầu nặng hơn cây cũ của tôi. Phông từ cuối sân nhẹ hơn, nhưng tới quả thứ ba trong pha cầu nhanh thì đã trễ.', 'published'::review_status, '2026-01-01T00:00:00.000Z'),
  ('rev-astrox-88d-pro-7', 'r-astrox-88d-pro', 'Trang V.', 'purchase'::review_tier, 'advanced'::skill_level, 'singles'::match_format, 'net'::court_position, 'BG65 Ti', 26, 4, 3, 4, 3, 'The shaft is softer than the marketing says. That suits me — smashes land where I aim rather than long.', 'Thân mềm hơn quảng cáo. Với tôi thì hợp — cú đập rơi đúng chỗ nhắm chứ không ra ngoài.', 'published'::review_status, '2026-01-16T00:00:00.000Z'),
