  ('rev-nanoflare-800-pro-9', 'r-nanoflare-800-pro', 'Bảo K.', 'purchase'::review_tier, 'advanced'::skill_level, 'doubles'::match_format, 'mid'::court_position, 'Aerobite', 23, 3, 4, 3.5, 3, 'Second one I have owned. Same weight, same balance out of the box, which is not true of every brand at this price.', 'Đây là cây thứ hai tôi dùng. Trọng lượng và cân bằng giống hệt cây đầu, điều mà không phải hãng nào ở tầm giá này cũng làm được.', 'published'::review_status, '2026-01-19T00:00:00.000Z'),
  ('rev-nanoflare-800-pro-10', 'r-nanoflare-800-pro', 'Nam Đ.', 'purchase'::review_tier, 'advanced'::skill_level, 'singles'::match_format, 'net'::court_position, 'Exbolt 63', 26, 4, 4.5, 4, 3, 'Holds shape after four months of twice-weekly play. Elbow gets sore if I string it any tighter.', 'Sau bốn tháng đánh hai buổi mỗi tuần vẫn giữ dáng. Căng cao hơn nữa là khuỷu tay đau.', 'published'::review_status, '2026-03-12T00:00:00.000Z'),
  ('rev-nanoflare-700-0', 'r-nanoflare-700', 'Thảo M.', 'purchase'::review_tier, 'intermediate'::skill_level, 'doubles'::match_format, 'net'::court_position, 'BG80', 25, 2.5, 4, 3.5, 4, 'Holds shape after four months of twice-weekly play. Elbow gets sore if I string it any tighter.', 'Sau bốn tháng đánh hai buổi mỗi tuần vẫn giữ dáng. Căng cao hơn nữa là khuỷu tay đau.', 'published'::review_status, '2026-04-22T00:00:00.000Z'),
  ('rev-nanoflare-700-1', 'r-nanoflare-700', 'Minh N.', 'purchase'::review_tier, 'advanced'::skill_level, 'singles'::match_format, 'mid'::court_position, 'BG65 Ti', 26, 3.5, 4, 3.5, 4, 'Strung at 26 lbs with BG80. Repulsion is fine, but the sweet spot is smaller than I expected for the price.', 'Đan BG80 ở 26 lbs. Độ nảy ổn, nhưng vùng ngọt nhỏ hơn tôi nghĩ so với mức giá.', 'published'::review_status, '2026-05-04T00:00:00.000Z'),
  ('rev-nanoflare-700-2', 'r-nanoflare-700', 'Hương T.', 'owner'::review_tier, 'advanced'::skill_level, 'doubles'::match_format, 'rear'::court_position, 'BG65 Ti', 27, 3, 3.5, 3.5, 3.5, 'Heavier through the head than my last frame. Clears are easier from the back, but the third shot in a fast exchange is late.', 'Đầu nặng hơn cây cũ của tôi. Phông từ cuối sân nhẹ hơn, nhưng tới quả thứ ba trong pha cầu nhanh thì đã trễ.', 'published'::review_status, '2026-03-15T00:00:00.000Z'),
  ('rev-nanoflare-700-3', 'r-nanoflare-700', 'Tuấn A.', 'owner'::review_tier, 'beginner'::skill_level, 'doubles'::match_format, 'mid'::court_position, 'BG65 Ti', 23, 3, 3.5, 4, 3.5, 'The shaft is softer than the marketing says. That suits me — smashes land where I aim rather than long.', 'Thân mềm hơn quảng cáo. Với tôi thì hợp — cú đập rơi đúng chỗ nhắm chứ không ra ngoài.', 'published'::review_status, '2026-08-11T00:00:00.000Z'),
